 function enterZone34(zone){if(!walk.on)walk.oldHideFloors=$('hideFloors').checked;$('hideFloors').checked=false;substation.decks.visible=true;walk.floor=zone==='ccm'?2.50:zone==='yard'?6.65:-.07;walk.zone=zone;walk.on=true;walk.bag=false;walk.journal=false;walk.crouch=false;walk.keys.clear();walk.inspection=false;walk.pitch=0;tool='hand';document.body.classList.add('walking31','practice26');document.body.classList.toggle('explore34',zone!=='plant');ui.hidden=false;if(zone==='ccm'){walk.pos.set(103.0,4.15,7.7);facePoint([103.0,3.82,4.85]);}else if(zone==='yard'){walk.pos.set(14.0,8.30,5.40);facePoint([11.6,7.95,3.9]);}else{walk.pos.set(1.8,1.58,4.1);facePoint([0,1.25,0]);}draw();if(zone!=='plant'){ui.querySelector('.w-top strong').textContent=zone==='ccm'?'CCM · recorrido de inspección':'Subestación · recorrido a pie';ui.querySelector('.w-top small').textContent='WASD mover · mouse mirar · Esc menú';}applyWalk(0);}
 function zoneStand34(x,z){if(window.Cabinets38?.blocks(x,z))return false;const r=.18,zone=walk.zone||'plant';if(zone==='ccm'){if(x<96.35||x>113.65||z<2.35||z>13.65)return false;if(x>97.35&&x<109.65&&z>3.50&&z<5.05)return false;for(const b of window.CCM34?.bounds()||[]){const inside=walk.pos.x>b.min.x-r&&walk.pos.x<b.max.x+r&&walk.pos.z>b.min.z-r&&walk.pos.z<b.max.z+r;if(!inside&&x>b.min.x-r&&x<b.max.x+r&&z>b.min.z-r&&z<b.max.z+r)return false;}return true;}return !!SiteWalk37.step({x:walk.pos.x,z:walk.pos.z,floor:walk.floor},x,z);}
 function turnButton34(code){const button=document.createElement('button');button.textContent=code==='ArrowLeft'?'↶':'↷';button.title=code==='ArrowLeft'?'Girar a la izquierda':'Girar a la derecha';button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture(e.pointerId);walk.keys.add(code);};button.onpointerup=button.onpointercancel=()=>walk.keys.delete(code);return button;}
