 function updateWalkZone37(zone){$('hideFloors').checked=false;substation.decks.visible=true;if(walk.zone===zone)return;walk.zone=zone;document.body.classList.toggle('explore34',zone!=='plant');
 // Walking upstairs keeps the work order, tool and progress instead of resetting the practice.
 for(const [group,visible]of practiceVisibility)group.visible=zone==='plant'?false:visible;
 for(const cut of ductCuts)cut.o.geometry=zone==='plant'&&index===4?cut.cut:cut.original;
 const title=ui.querySelector('.w-top strong'),subtitle=ui.querySelector('.w-top small');
 if(title)title.textContent=zone==='plant'?'Recorrido de mantenimiento · G-01':zone==='stairs'?'Escalera · planta / subestación':'Subestación · recorrido a pie';
 if(subtitle)subtitle.textContent=zone==='plant'?'Q · orden de mantenimiento conservada':zone==='stairs'?'WASD para subir o bajar · barandales sólidos':'Regresa por la misma escalera para continuar la orden';
 renderer.shadowMap.needsUpdate=true;
 }
 function moveWalk37(x,z){if(window.Cabinets38?.blocks(x,z))return;if(walk.zone==='ccm'){if(canStand(x,z)){walk.pos.x=x;walk.pos.z=z;}return;}
 const next=SiteWalk37.step({x:walk.pos.x,z:walk.pos.z,floor:walk.floor},x,z);if(!next)return;walk.pos.x=x;walk.pos.z=z;walk.floor=next.height;updateWalkZone37(next.zone);
 }
 function reach(id){const o=targets.get(id);if(!o)return Infinity;return o.getWorldPosition(new T.Vector3()).distanceTo(walk.pos);}
 function centerPick(){if(walk.zone&&walk.zone!=='plant')return null;const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(0,0),camera);service.updateWorldMatrix(true,false);for(const o of targets.values())o.updateWorldMatrix(false,false);return ray.intersectObjects(needed().map(id=>targets.get(id)),false)[0]?.object.userData.workTarget;}
 function facePoint(point){const d=new T.Vector3(...point).sub(walk.pos);walk.yaw=Math.atan2(-d.x,-d.z);walk.pitch=Math.max(-1.25,Math.min(1.25,Math.atan2(d.y,Math.hypot(d.x,d.z))));}
 function beginWalk(){walk.floor=-.07;walk.zone='plant';document.body.classList.remove('explore34');if(!walk.on){walk.oldFov=camera.fov;walk.oldHideFloors=$('hideFloors').checked;}$('hideFloors').checked=false;substation.decks.visible=true;walk.on=true;walk.bag=false;walk.journal=true;walk.keys.clear();walk.crouch=false;walk.pos.set(1.8,1.58,4.1);walk.inspection=false;walk.bagGoal=false;walk.journal=false;facePoint([0,1.25,0]);camera.fov=68;camera.near=.055;camera.updateProjectionMatrix();spinning=false;campusNav.tour=false;document.body.classList.add('walking31');brush.visible=false;applyWalk(0);}
