 function lockLook(){if(!walk.on)return;setGamePause(false);setBag(false);walk.journal=false;draw();try{if(!canvas.requestPointerLock)throw Error('Pointer lock unavailable');const p=canvas.requestPointerLock();p?.catch(()=>{setGamePause(false);say('El navegador no permitió capturar el mouse. Usa botón derecho + arrastrar o las flechas.',true);});}catch(e){say('Mira con botón derecho + arrastrar; F vuelve a intentar capturar el mouse.',true);}}
 const gameMenu=document.createElement('section');gameMenu.id='walkGameMenu';gameMenu.hidden=true;gameMenu.setAttribute('role','dialog');gameMenu.setAttribute('aria-modal','true');gameMenu.setAttribute('aria-labelledby','walkMenuTitle');
 gameMenu.innerHTML='<div class="walk-menu-card"><span class="walk-eyebrow">RECORRIDO DE MANTENIMIENTO</span><h2 id="walkMenuTitle">Recorrido en pausa</h2><p>Explora la instalación y realiza las prácticas sobre el equipo.</p><div class="walk-bindings"><span><kbd>W A S D</kbd> Moverte</span><span><kbd>Mouse</kbd> Mirar libremente</span><span><kbd>E / clic</kbd> Interactuar</span><span><kbd>C</kbd> Agacharte / levantarte</span><span><kbd>Shift</kbd> Paso rápido</span><span><kbd>B</kbd> Bolsa en el piso</span><span><kbd>Q</kbd> Objetivo y cuaderno</span><span><kbd>Z</kbd> Inspeccionar</span><span><kbd>H</kbd> Manos libres</span><span><kbd>Esc / F1</kbd> Menú y controles</span></div><p class="walk-menu-note">Al continuar se captura el mouse. Esc lo libera. Si tu navegador no lo permite, mantén el botón derecho y arrastra para mirar.</p><label>Sensibilidad <input id="walkSensitivity" aria-label="Sensibilidad del mouse" type="range" min="1" max="6" value="3" step="0.5"></label><button id="walkResume">Continuar · capturar mouse</button><button id="walkFreeCursor">Continuar con cursor libre</button></div>';
 $('viewer').append(gameMenu);let lookSensitivity=.003;
 $('walkSensitivity').oninput=e=>lookSensitivity=Number(e.target.value)/1000;
 $('walkResume').onclick=lockLook;$('walkFreeCursor').onclick=()=>setGamePause(false);
 function setGamePause(value){walk.paused=!!value;walk.keys.clear();walk.look=null;walk.ratchetDrag=null;gameMenu.hidden=!value;document.body.classList.toggle('walk-paused',!!value);if(value){if(document.pointerLockElement===canvas)document.exitPointerLock();$('walkResume').focus();}}
 let hadMouseLock=false;
 document.addEventListener('pointerlockchange',()=>{const locked=document.pointerLockElement===canvas;document.body.classList.toggle('mouse-captured',locked);walk.keys.clear();walk.look=null;if(hadMouseLock&&!locked&&walk.on&&!walk.bag&&!walk.journal&&!walk.paused)setGamePause(true);hadMouseLock=locked;});
 document.addEventListener('keydown',e=>{if(walk.paused&&e.code==='Tab'){const items=[...gameMenu.querySelectorAll('button,input')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
